insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-08', 'k-central', 3, 'إذا كان المتوسط الحسابي للقيم (4، 7، 9، س) يساوي 7، فما قيمة س؟', '["6","7","8","10"]'::jsonb, 2, 'المجموع المطلوب = 7 × 4 = 28، ومجموع المعلوم = 20، فقيمة س = 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-09', 'k-central', 3, 'شعبة (أ) فيها 10 طلاب متوسط درجاتهم 8، وشعبة (ب) فيها 20 طالباً متوسط درجاتهم 11. ما المتوسط الحسابي لدرجات الشعبتين معاً؟', '["9","9.5","10","10.5"]'::jsonb, 2, 'المتوسط الموزون = (10×8 + 20×11) ÷ 30 = (80 + 220) ÷ 30 = 300 ÷ 30 = 10.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-10', 'k-central', 3, 'حصل طالب على 6 درجات في مقرر عدد ساعاته 3، و9 درجات في مقرر عدد ساعاته 2، و12 درجة في مقرر عدد ساعاته 1. ما متوسطه الموزون؟', '["8","9","7.5","10"]'::jsonb, 0, '(6×3 + 9×2 + 12×1) ÷ (3+2+1) = (18 + 18 + 12) ÷ 6 = 48 ÷ 6 = 8.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-11', 'k-central', 2, 'ما مقياس النزعة المركزية الوحيد المناسب لتحديد المادة الدراسية المفضلة لدى طلاب الصف؟', '["المتوسط الحسابي","الوسيط","المنوال","المدى"]'::jsonb, 2, 'البيانات اسمية (أسماء مواد)، والمنوال هو المقياس الوحيد الصالح للبيانات الاسمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-12', 'k-central', 3, 'أي مقاييس النزعة المركزية أنسب لتمثيل هذه القيم: 3، 5، 4، 6، 5، 40؟', '["المتوسط الحسابي","الوسيط","المنوال","المدى"]'::jsonb, 1, 'وجود قيمة متطرفة (40) يجعل المتوسط مضللاً، والوسيط لا يتأثر بالقيم الشاذة فهو الأنسب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-13', 'k-central', 2, 'أي العبارات الآتية لا تُعد من خصائص المتوسط الحسابي؟', '["تدخل جميع القيم في حسابه","يتأثر بالقيم المتطرفة","يُستخدم مع البيانات الاسمية","هو الأساس في الإحصاء الاستدلالي"]'::jsonb, 2, 'المتوسط لا يصلح للبيانات الاسمية (لا معنى لمتوسط الألوان مثلاً)؛ فهي من خصائص المنوال.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-14', 'k-central', 1, 'ما المدى للقيم: 15، 8، 12, 20، 5؟', '["10","12","15","20"]'::jsonb, 2, 'المدى = أعلى قيمة − أدنى قيمة = 20 − 5 = 15.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-15', 'k-central', 2, 'درجات صفين في اختبار واحد: الانحراف المعياري للصف الأول 2.1 وللصف الثاني 7.4. ما الاستنتاج الصحيح؟', '["الصف الأول درجاته أكثر تجانساً","الصف الثاني درجاته أكثر تجانساً","متوسط الأول أعلى حتماً","لا يمكن مقارنة التجانس"]'::jsonb, 0, 'كلما قل الانحراف المعياري كانت الدرجات أقرب لبعضها وأكثر تجانساً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-16', 'k-central', 2, 'أي مقاييس التشتت الآتية لا يتأثر بالقيم المتطرفة؟', '["المدى","المدى الربيعي","الانحراف المتوسط","التباين"]'::jsonb, 1, 'المدى الربيعي يعتمد على الربيعين الأعلى والأدنى ويستبعد طرفي التوزيع، فلا يتأثر بالشواذ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-17', 'k-central', 2, 'إذا كان الانحراف المعياري لدرجات صف يساوي صفراً، فهذا يعني أن:', '["جميع الدرجات متساوية","الدرجات شديدة التشتت","المتوسط يساوي صفراً","نصف الدرجات فوق المتوسط"]'::jsonb, 0, 'انحراف معياري = صفر يعني لا يوجد أي انحراف عن المتوسط، أي أن كل القيم متطابقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-18', 'k-central', 2, 'القيمة التي يقل عنها 50% من الدرجات وتزيد عنها 50% هي:', '["المتوسط الحسابي","الوسيط","المنوال","الربيع الأعلى"]'::jsonb, 1, 'هذا هو تعريف الوسيط: منتصف التوزيع بعد الترتيب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-01', 'l-imla', 1, 'أي الكلمات الآتية همزتها همزة قطع؟', '["استخرج","انطلق","أكرم","اجتهد"]'::jsonb, 2, '«أكرم» فعل رباعي وهمزة الرباعي (ماضيه وأمره ومصدره) همزة قطع. أما استخرج (سداسي) وانطلق واجتهد (خماسيان) فهمزتها وصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-02', 'l-imla', 1, 'أي الكلمات الآتية همزتها همزة وصل؟', '["أخذ","إيمان","استعمال","أرسل"]'::jsonb, 2, '«استعمال» مصدر سداسي وهمزته وصل. أما أخذ (ماضي ثلاثي مهموز) وإيمان وأرسل فهمزات قطع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-03', 'l-imla', 2, 'ما الجملة المكتوبة إملائياً بصورة صحيحة؟', '["ذهب إبني إلى المدرسة","ذهب ابني إلى المدرسة","ذهب أبني إلا المدرسة","ذهب ابنى إلى المدرسه"]'::jsonb, 1, '«ابن» من الأسماء المسموعة بهمزة وصل، و«إلى» بهمزة قطع مع ألف مقصورة، و«المدرسة» بتاء مربوطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-04', 'l-imla', 2, 'سبب كتابة الهمزة على نبرة في كلمة «سُئِل»:', '["الكسرة أقوى من الضمة","الفتحة أقوى من الكسرة","الهمزة متطرفة","ما قبلها ساكن"]'::jsonb, 0, 'الهمزة مكسورة وما قبلها مضموم، والكسرة أقوى الحركات فتكتب على ياء (نبرة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-05', 'l-imla', 2, 'ما الكتابة الصحيحة لمصدر الفعل «أجابَ»؟', '["اجابة","إجابة","أجابه","إجابه"]'::jsonb, 1, 'مصدر الرباعي همزته قطع مكسورة (إجابة)، وتختم بتاء مربوطة لأنها تنطق هاء عند الوقف وتاءً عند الوصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-06', 'l-imla', 2, 'أي الكلمات الآتية كتبت همزتها المتطرفة بصورة صحيحة لمناسبة حركة ما قبلها؟', '["شاطِأ","تباطُؤ","قارِؤ","خطاء"]'::jsonb, 1, '«تباطُؤ» قبل همزتها ضمة فتكتب على واو. الصواب: شاطئ وقارئ (قبلهما كسرة → ياء)، وخطأ (قبلها فتحة → ألف).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-07', 'l-imla', 2, 'كتبت الألف اللينة قائمة في الفعل «دعا» لأن:', '["أصلها ياء","أصلها واو","الفعل فوق ثلاثي","الكلمة أعجمية"]'::jsonb, 1, 'أصل الألف واو (يدعو)، والثلاثي الواوي الأصل تكتب ألفه قائمة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-08', 'l-imla', 2, 'أي الكلمات الآتية تكتب ألفها المتطرفة مقصورة (ى)؟', '["عصا","سما","هد_","دنيا"]'::jsonb, 2, '«هدى» أصل ألفه ياء (يهدي) فتكتب مقصورة. عصا وسما أصلهما واو، ودنيا سبقت ألفها بياء فتكتب قائمة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-09', 'l-imla', 3, 'ما الكلمة التي كتبت بصورة صحيحة فيما يأتي؟', '["مستشفا","مستشفى","مستشفي","مصطفا"]'::jsonb, 1, '«مستشفى» فوق ثلاثية غير مسبوقة ألفها بياء فتكتب مقصورة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-10', 'l-imla', 1, 'أي الكلمات الآتية تنتهي بتاء مفتوحة؟', '["مدرسة","قضاة","معلومات","شجرة"]'::jsonb, 2, '«معلومات» جمع مؤنث سالم وتاؤه مفتوحة تنطق تاءً دائماً. والبقية تاؤها مربوطة تنطق هاءً عند الوقف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-11', 'l-imla', 2, 'ما الجملة الصحيحة إملائياً؟', '["قرأة الطالبة القصة","قرأت الطالبة القصه","قرأت الطالبة القصة","قرآت الطالبه القصة"]'::jsonb, 2, '«قرأتْ» فعل ماضٍ بتاء التأنيث الساكنة المفتوحة، و«القصة» اسم مختوم بتاء مربوطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-12', 'l-imla', 3, 'كتبت الهمزة على السطر في كلمة «قراءة» لأن:', '["الهمزة مفتوحة بعد ألف ساكنة","الهمزة مضمومة بعد واو","ما قبلها مكسور","الهمزة في أول الكلمة"]'::jsonb, 0, 'الهمزة المتوسطة المفتوحة بعد ألف مد ساكنة تكتب مفردة على السطر: قراءة، عباءة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-13', 'l-imla', 2, 'حيلة تُعرف بها همزة الوصل من همزة القطع بإدخال حرف قبل الكلمة. أي حرف يصلح لذلك؟', '["الباء","الواو أو الفاء","اللام","السين"]'::jsonb, 1, 'أدخل الواو أو الفاء: إن نطقت الهمزة (وَأَكرمَ) فهي قطع، وإن سقطت نطقاً (وَاستعمل) فهي وصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-14', 'l-imla', 2, 'ما الصواب في كتابة الفعل الماضي من «يسمو»؟', '["سمى","سما","سمي","سماء"]'::jsonb, 1, 'أصل الألف واو (يسمو)، فتكتب ألفاً قائمة: سما.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('li-15', 'l-imla', 3, 'أي مجموعة كتبت كلماتها جميعاً كتابة صحيحة؟', '["مسؤول، رؤية، فِئة","مسئول، رءية، فئه","مسؤل، رؤيه، فيئة","مسوول، روية، فئة"]'::jsonb, 0, 'مسؤول ورؤية: الهمزة مضمومة أو ساكنة بعد ضم تكتب على واو، وفئة: الهمزة مكسورة على نبرة، والتاء مربوطة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-01', 'l-nahw', 1, 'من علامات الاسم التي يتميز بها عن الفعل والحرف:', '["قبول قد والسين","قبول تاء التأنيث الساكنة","قبول التنوين والجر والنداء","قبول سوف"]'::jsonb, 2, 'الاسم يقبل التنوين والجر والنداء وأل التعريف، أما قد والسين وسوف وتاء التأنيث الساكنة فعلامات الفعل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-02', 'l-nahw', 2, '«إنّ المعلمين مخلصون». ضبطت كلمة «المعلمين» بالياء لأنها:', '["خبر إن مرفوع","اسم إن منصوب بالياء لأنه جمع مذكر سالم","مضاف إليه مجرور","فاعل مرفوع"]'::jsonb, 1, 'إنّ تنصب الاسم وترفع الخبر، وجمع المذكر السالم ينصب بالياء، وخبرها «مخلصون» مرفوع بالواو.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-03', 'l-nahw', 2, 'ما الجملة التي جاء فيها خبر كان منصوباً بصورة صحيحة؟', '["كان الجوُّ صحوٌ","كان الجوُّ صحواً","كان الجوَّ صحواً","كان الجوِّ صحوٍ"]'::jsonb, 1, 'كان ترفع الاسم (الجوُّ) وتنصب الخبر (صحواً).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-04', 'l-nahw', 1, 'الحرف الناسخ الذي يفيد التمني هو:', '["لعلّ","ليت","كأنّ","لكنّ"]'::jsonb, 1, 'ليت للتمني (طلب المستحيل أو بعيد التحقق)، ولعل للترجي، وكأن للتشبيه، ولكن للاستدراك.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-05', 'l-nahw', 2, '«الطلاب يجتهدون في دروسهم». الفعل «يجتهدون» مرفوع وعلامة رفعه:', '["الضمة الظاهرة","ثبوت النون لأنه من الأفعال الخمسة","الواو","الألف"]'::jsonb, 1, 'اتصلت به واو الجماعة فهو من الأفعال الخمسة، ترفع بثبوت النون وتنصب وتجزم بحذفها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-06', 'l-nahw', 2, 'ما الجملة الصحيحة نحوياً؟', '["الطالبان لم يحضرا الدرس","الطالبان لم يحضران الدرس","الطالبان لم يحضروا الدرس","الطالبان لم يحضرون الدرس"]'::jsonb, 0, '«لم» تجزم الفعل، والأفعال الخمسة تجزم بحذف النون: لم يحضرا. والفاعل مثنى فتلزم ألف الاثنين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-07', 'l-nahw', 3, '«صلّيتُ في مساجدَ عدةٍ». جُرّت كلمة «مساجد» بالفتحة لأنها:', '["مضاف إليه","ممنوعة من الصرف (صيغة منتهى الجموع)","جمع مؤنث سالم","اسم مقصور"]'::jsonb, 1, '«مساجد» على صيغة منتهى الجموع فهي ممنوعة من الصرف، تجر بالفتحة نيابة عن الكسرة ما لم تُعرَّف بأل أو تُضف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-08', 'l-nahw', 2, 'ما الضبط الصحيح للعدد والمعدود؟', '["اشتريت ثلاثةَ كتبٍ","اشتريت ثلاثَ كتبٍ","اشتريت ثلاثةُ كتاباً","اشتريت ثلاثاً كتبٍ"]'::jsonb, 0, 'الأعداد 3–10 تخالف المعدود في التذكير والتأنيث؛ «كتب» مفردها مذكر (كتاب) فالعدد بالتاء: ثلاثة كتبٍ، والمعدود جمع مجرور.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-09', 'l-nahw', 2, 'ما الجملة الصحيحة في تمييز ألفاظ العقود؟', '["أنفق تسعون ريالاً","أنفقتُ تسعين ريالاً","أنفقتُ تسعين ريالات","أنفقتُ تسعون ريالٍ"]'::jsonb, 1, 'تسعين منصوبة بالياء لأنها مفعول به ملحق بجمع المذكر السالم، وتمييز ألفاظ العقود مفرد منصوب: ريالاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-10', 'l-nahw', 3, 'ما الصواب في قولنا؟', '["حضر أحدَ عشرَ طالباً","حضر أحدُ عشرَ طالباً","حضر إحدى عشر طالباً","حضر أحد عشرة طالباً"]'::jsonb, 1, 'العدد 11 مبني على فتح الجزأين في محل رفع فاعل (أحدَ عشرَ)، لكن الأفصح المتداول في الاختبارات: «أحدَ عشرَ» بفتح الجزأين، والفاعل محلاً مرفوع، والمعدود مفرد منصوب. الخيار (ب) يضبط الجزء الأول بالضم وهو خطأ شائع، والصحيح الخيار الأول.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-11', 'l-nahw', 2, 'ما التصويب الصحيح لعبارة «الطاقة الغير مفيدة»؟', '["الطاقة الغير المفيدة","الطاقة غير المفيدة","طاقة الغير مفيدة","الطاقة الغيرية المفيدة"]'::jsonb, 1, '«غير» لا تدخل عليها أل، والصواب إضافة «غير» إلى الصفة المعرفة: الطاقة غيرُ المفيدة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-12', 'l-nahw', 2, 'ما التصويب الصحيح لعبارة «أهلاً وسهلاً بعملاؤنا الكرام»؟', '["بعملائِنا الكرام","بعملاؤنا الكرامِ","بعملاءنا الكرام","العبارة صحيحة"]'::jsonb, 0, 'الاسم بعد الباء مجرور: بعملائِنا، وتكتب الهمزة على ياء لأنها مكسورة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-13', 'l-nahw', 2, 'ما الصواب فيما يأتي؟', '["راجعتُ إحدى المستشفيات","راجعتُ أحد المستشفيات","راجعت إحدى المستشفى","راجعت واحدة المستشفيات"]'::jsonb, 1, '«المستشفى» مذكر (مكان الاستشفاء)، فيقال: أحد المستشفيات. أما إحدى فللمؤنث (إحدى القاعات).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-14', 'l-nahw', 3, '«ما زال المطرُ منهمراً». عمل «ما زال» هنا:', '["نصب المبتدأ ورفع الخبر","رفع الاسم ونصب الخبر","جزم الفعلين","لا عمل لها"]'::jsonb, 1, 'ما زال من أخوات كان: ترفع الاسم (المطرُ) وتنصب الخبر (منهمراً)، وتفيد الاستمرار.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-15', 'l-nahw', 2, 'ما الجملة التي تقدم فيها الخبر على المبتدأ وجوباً؟', '["العلمُ نورٌ","في الصفِّ طالبٌ مجتهدٌ","المعلمُ حاضرٌ","الاجتهادُ طريقُ النجاح"]'::jsonb, 1, 'إذا كان المبتدأ نكرة والخبر شبه جملة (في الصف) وجب تقديم الخبر: في الصفِّ طالبٌ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-16', 'l-nahw', 3, 'أي الأفعال الآتية من الأفعال الخمسة؟', '["يكتبْنَ","تكتبين","كتبوا","نكتب"]'::jsonb, 1, '«تكتبين» مضارع اتصلت به ياء المخاطبة. أما يكتبن (نون النسوة ليس منها) وكتبوا (ماضٍ) ونكتب (لم يتصل به شيء).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-17', 'l-nahw', 2, 'ما إعراب كلمة «نورٌ» في جملة «العلمُ نورٌ»؟', '["فاعل مرفوع","خبر مرفوع","مبتدأ مرفوع","مفعول به منصوب"]'::jsonb, 1, 'العلم مبتدأ مرفوع، ونور خبره مرفوع بالضمة، وهي جملة اسمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ln-18', 'l-nahw', 3, 'ما التصويب الأدق لعبارة «الحضور قاصر على المعلمين»؟', '["الحضور مقصور على المعلمين","الحضور قاصراً على المعلمين","الحضور مقتصر إلى المعلمين","العبارة صحيحة"]'::jsonb, 0, 'يقال: قُصر الشيء على كذا فهو مقصور عليه. أما «قاصر» فمعناها عاجز أو لم يبلغ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lt-01', 'l-tarqeem', 1, 'العلامة المناسبة بين جملتين إحداهما سبب في الأخرى هي:', '["النقطة (.)","الفاصلة (،)","الفاصلة المنقوطة (؛)","النقطتان (:)"]'::jsonb, 2, 'الفاصلة المنقوطة توضع بين جملتين بينهما سببية أو نتيجة: «اجتهد الطالب؛ فتفوق».') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
